configuration.jsScript:
var status = metadata.spcStatus;
var routes = [];

// 1. Always route to Freeze if the flag is there to ensure the save happens
if (metadata.shouldFreeze === 'true') {
    routes.push('Freeze Limits');
}

// 2. Always allow 'Out of Control' messages through, even during a freeze
if (status === 'Out of Control') {
    routes.push('Out of Control');
} 

// 3. ONLY route to 'Normal' if we AREN'T currently freezing
else if (status === 'Normal' && metadata.shouldFreeze !== 'true') {
    routes.push('Normal');
}

return routes;

