configuration.jsScript:
// 1. Setup & Dynamic Limit Extraction
// Prioritize the Server Attribute (ss_start_ts) to ensure reset works
var start = Number(metadata.ss_start_ts || 0); 
var now = new Date().getTime();

// Fetch the user-defined limit. Default to 60.
var userLimitSeconds = parseFloat(metadata.ss_calibration_limit || 60);
var userLimitMs = userLimitSeconds * 1000;

var history = [];

// CRITICAL FIX: If start is 0, elapsed must be 0
var elapsedMs = (start > 0) ? (now - start) : 0;

try {
    history = JSON.parse(metadata.total_rms || '[]');
} catch (e) {
    history = [];
}
history.unshift({ ts: now, value: parseFloat(msg.total_rms) });
if (history.length > 90) {
    history = history.slice(0, 90); 
}

// 2. Robust Frozen Check
var savedUcl = metadata.ss_ucl || metadata.ss_ss_ucl;
var savedLcl = metadata.ss_lcl || metadata.ss_ss_lcl;
var savedMean = metadata.ss_mean || metadata.ss_ss_mean;

var isAlreadyFrozen = (savedUcl !== undefined && savedUcl !== null && savedUcl !== 'null');

// 3. Reset temporary flags
delete metadata.shouldFreeze;
delete metadata.shouldSaveStart;

// 4. Logic Branching
if (isAlreadyFrozen) {
    // LOCK MODE: Use saved attributes only
    msg.ucl = parseFloat(savedUcl);
    msg.lcl = parseFloat(savedLcl);
    msg.mean = parseFloat(savedMean);
} else if (history.length >= 20) {
    // CALIBRATION MODE: Live Math
    var values = history.map(function(item) { return parseFloat(item.value || item.v || 0); });
    var sum = 0;
    for(var i=0; i<values.length; i++) { sum += values[i]; }
    var mean = sum / values.length;

    var sqDiffSum = 0;
    for(var j=0; j<values.length; j++) { sqDiffSum += Math.pow(values[j] - mean, 2); }
    var sigma = Math.sqrt(sqDiffSum / values.length);

    msg.ucl = mean + (3 * sigma);
    msg.lcl = mean - (3 * sigma);
    msg.mean = mean;

    // Trigger transition if dynamic time is up
    if (start > 0 && elapsedMs >= userLimitMs) { 
        metadata.shouldFreeze = 'true';
        msg.ss_ucl = msg.ucl;
        msg.ss_lcl = msg.lcl;
        msg.ss_mean = msg.mean;
    }
}

// 5. Cleanup & Debug
var currentRMS = parseFloat(msg.total_rms || 0);
var uclLimit = msg.ucl || 999;
var lclLimit = msg.lcl || -999;
metadata.spcStatus = (currentRMS > uclLimit || currentRMS < lclLimit) ? 'Out of Control' : 'Normal';

metadata.debug_trace = JSON.stringify({
    "isAlreadyFrozen": isAlreadyFrozen,
    "final_ucl_used": msg.ucl,
    "shouldFreeze": metadata.shouldFreeze === 'true',
    "startTime": start,
    "currentTime": now,
    "calibrationLimit": userLimitSeconds, // Track the limit used in debug
    "elapsedSeconds": (elapsedMs / 1000).toFixed(2)
});

delete metadata.total_rms;
delete metadata.fft_amplitudes;

// 6. Return Logic (Standard TB Multi-output format)
var elapsedSeconds = parseFloat((elapsedMs / 1000).toFixed(2));
msg.elapsedSeconds = elapsedSeconds;

if (metadata.shouldFreeze === 'true') {
    var attributeMsg = {
        msg: { ss_ucl: msg.ucl, ss_lcl: msg.lcl, ss_mean: msg.mean }, 
        metadata: metadata, 
        msgType: 'POST_ATTRIBUTES_REQUEST'
    };

    var telemetryMsg = {
        msg: JSON.parse(JSON.stringify(msg)), 
        metadata: JSON.parse(JSON.stringify(metadata)),
        msgType: 'POST_TELEMETRY_REQUEST'
    };
    telemetryMsg.metadata.ss_ucl = msg.ucl.toString(); 
    delete telemetryMsg.metadata.shouldFreeze;

    return [attributeMsg, telemetryMsg];
}

return {msg: msg, metadata: metadata, msgType: msgType};

// 1. Clean up heavy data to avoid truncation errors
delete msg.freq_bins;
delete msg.amplitudes;

// 2. Handle the calibration timestamp
if (msg.start_ts) {
    // Save to DB as 'start_ts'. ThingsBoard will add 'ss_' during the next fetch.
    var attributeData = { start_ts: msg.start_ts };

    // Inject into metadata immediately so the current message doesn't have startTime: 0
    metadata.ss_start_ts = msg.start_ts.toString();

    return [
        { msg: attributeData, metadata: metadata, msgType: 'POST_ATTRIBUTES_REQUEST' },
        { msg: msg, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST' }
    ];
}

return { msg: msg, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST' };

var routes = [];

// 1. Route for saving the timestamp to the server
if (msgType === 'POST_ATTRIBUTES_REQUEST') {
    routes.push('Attribute Path');
}

// 2. Route for the actual data intended for the SPC calculation
if (msgType === 'POST_TELEMETRY_REQUEST') {
    routes.push('Telemetry Path');
}

return routes;

